  "clauses": [
    {
      "id": "c1",
      "title": "Rent Amount",
      "content": "Monthly rent shall be Rs. 75,000 payable by the 5th of every month via bank transfer.",
      "category": "financial"
    },
    {
      "id": "c2",
      "title": "Security Deposit",
      "content": "Tenant shall deposit Rs. 10,00,000 as refundable security deposit before possession.",
      "category": "financial"
    },
    {
      "id": "c3",
      "title": "Lock-in Period",
      "content": "The agreement shall have a lock-in period of 12 months from the date of commencement.",
      "category": "duration"
    },
    {
      "id": "c4",
      "title": "Maintenance & Repairs",
      "content": "Tenant shall handle interior maintenance; structural repairs shall be the responsibility of the Landlord.",
      "category": "maintenance"
    },
    {
      "id": "c5",
      "title": "Termination Clause",
      "content": "Either party may terminate with 3 months written notice after the lock-in period.",
      "category": "termination"
    }
  ]
}
